-- ============================================================================
-- B5 FOLLOW-ON W1, D4 PART C: the open-book label on the basin capstone
-- brief.
--
-- WHY. A lesson or a panel's opening view prints the answers these capstones
-- grade (docs/graded-field-audit/README.md finding 3; FOLLOW-ON-PROGRAMME.md
-- section 3). Until W5 re-cases or strips them, the brief says so. The label is
-- the brief's first sentence; the rest of the prompt is unchanged. The same
-- note heads the tier's capstone lesson (NextGen zip).
--
-- beginner: every graded figure(s) printed; section 3 pick A (re-case)
-- intermediate: every graded figure(s) printed; section 3 pick A (re-case)
-- advanced: every graded figure(s) printed; section 3 pick A (re-case)
--
-- THE LABEL:
--   Open book: the figures this capstone grades can be read in this tier's
--   lessons or on a panel as it opens, so for now it checks that you can find,
--   read and report each one correctly. A later update moves it to a case of its
--   own.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance), title, dataset, status and the row. The guard requires `fields`
-- to equal its post-20261024a value exactly, before and after, so no answer
-- grades differently and no attempt guard is needed.
--
-- GUARDS. Each prompt must hold its post-20261024a text (md5, rewritten) or
-- its labelled text (left alone). Anything else raises and the file rolls
-- back. Runs after 20261024a_w1_*. Generated by
-- docs/graded-field-audit/w1_capstones.py. SAFE TO RE-RUN.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_allow    jsonb := '{}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
  v_s1       text;
  v_s2       text;
begin
  -- basin / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'basin' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w1 open-book basin refused: basin/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'cdd601a8d0222c9cf090e930d9419415' and fields = '[{"key": "solid_100", "tol": 0.05, "unit": "m", "label": "Solid thickness in 100 m of surface shale", "expected": 38.57953418711555}, {"key": "restored", "tol": 0.05, "unit": "m", "label": "100 m shale from 1000 m, restored to surface", "expected": 159.79553483785466}, {"key": "phi_2000", "tol": 0.001, "unit": "v/v", "label": "Shale porosity at 2000 m", "expected": 0.22717481230903933}, {"key": "t_first", "tol": 0.05, "unit": "degC", "label": "Temperature at the first cell (50 m)", "expected": 11.666666666666671}, {"key": "t_lowk_base", "tol": 0.05, "unit": "degC", "label": "Temperature at the low-k base (950 m)", "expected": 41.66666666666673}, {"key": "t_deepest", "tol": 0.05, "unit": "degC", "label": "Temperature at the deepest cell (1950 m)", "expected": 59.619047619047684}]'::jsonb then 'old'
              when md5(prompt) = '844a4224438738a8982ca478e1264f63' and fields = '[{"key": "solid_100", "tol": 0.05, "unit": "m", "label": "Solid thickness in 100 m of surface shale", "expected": 38.57953418711555}, {"key": "restored", "tol": 0.05, "unit": "m", "label": "100 m shale from 1000 m, restored to surface", "expected": 159.79553483785466}, {"key": "phi_2000", "tol": 0.001, "unit": "v/v", "label": "Shale porosity at 2000 m", "expected": 0.22717481230903933}, {"key": "t_first", "tol": 0.05, "unit": "degC", "label": "Temperature at the first cell (50 m)", "expected": 11.666666666666671}, {"key": "t_lowk_base", "tol": 0.05, "unit": "degC", "label": "Temperature at the low-k base (950 m)", "expected": 41.66666666666673}, {"key": "t_deepest", "tol": 0.05, "unit": "degC", "label": "Temperature at the deepest cell (1950 m)", "expected": 59.619047619047684}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'basin' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w1 open-book basin refused: basin/beginner matches neither its published form (prompt md5 cdd601a8d0222c9cf090e930d9419415) nor its W1 form (prompt md5 844a4224438738a8982ca478e1264f63), with the fields this file was generated against';
  end if;

  -- basin / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'basin' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w1 open-book basin refused: basin/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'e9020a66661a15a5e6d398da869922e0' and fields = '[{"key": "ro_f0", "tol": 0.001, "unit": "%Ro", "label": "Ro at zero reaction", "expected": 0.20189651799465538}, {"key": "ro_full", "tol": 0.005, "unit": "%Ro", "label": "Ro at full reaction", "expected": 4.687971627022019}, {"key": "ro_150_r3", "tol": 0.002, "unit": "%Ro", "label": "Ro at 150 C on the 3 C/Ma ramp", "expected": 0.9871413464062039}, {"key": "ro_150_r1", "tol": 0.002, "unit": "%Ro", "label": "Ro at 150 C on the 1 C/Ma ramp", "expected": 1.1129254516555198}, {"key": "tr_10", "tol": 0.0005, "unit": "frac", "label": "Type II TR after 10 Ma at 100 C", "expected": 0.022481215976523083}, {"key": "tr_50", "tol": 0.0005, "unit": "frac", "label": "Type II TR after 50 Ma at 100 C", "expected": 0.05477927380797565}]'::jsonb then 'old'
              when md5(prompt) = '070f9311e9275c498804b1ec915a5433' and fields = '[{"key": "ro_f0", "tol": 0.001, "unit": "%Ro", "label": "Ro at zero reaction", "expected": 0.20189651799465538}, {"key": "ro_full", "tol": 0.005, "unit": "%Ro", "label": "Ro at full reaction", "expected": 4.687971627022019}, {"key": "ro_150_r3", "tol": 0.002, "unit": "%Ro", "label": "Ro at 150 C on the 3 C/Ma ramp", "expected": 0.9871413464062039}, {"key": "ro_150_r1", "tol": 0.002, "unit": "%Ro", "label": "Ro at 150 C on the 1 C/Ma ramp", "expected": 1.1129254516555198}, {"key": "tr_10", "tol": 0.0005, "unit": "frac", "label": "Type II TR after 10 Ma at 100 C", "expected": 0.022481215976523083}, {"key": "tr_50", "tol": 0.0005, "unit": "frac", "label": "Type II TR after 50 Ma at 100 C", "expected": 0.05477927380797565}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'basin' and tier = 'intermediate' and active;
  if v_s1 = 'other' then
    raise exception 'w1 open-book basin refused: basin/intermediate matches neither its published form (prompt md5 e9020a66661a15a5e6d398da869922e0) nor its W1 form (prompt md5 070f9311e9275c498804b1ec915a5433), with the fields this file was generated against';
  end if;

  -- basin / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'basin' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w1 open-book basin refused: basin/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '47145f31ec835cc158251fb51e5679c6' and fields = '[{"key": "final_ro", "tol": 0.002, "unit": "%Ro", "label": "Source rock final Ro", "expected": 1.6718288798752388}, {"key": "final_temp", "tol": 0.1, "unit": "degC", "label": "Source rock final temperature", "expected": 149.76037539670858}, {"key": "final_tr", "tol": 0.002, "unit": "frac", "label": "Final transformation ratio", "expected": 0.7423743797385286}, {"key": "generated", "tol": 5, "unit": "kg/m2", "label": "Generated mass at present day", "expected": 13946.54641524398}, {"key": "expelled", "tol": 5, "unit": "kg/m2", "label": "Expelled mass at present day", "expected": 10048.985378825158}, {"key": "ro_delta", "tol": 0.001, "unit": "%Ro", "label": "Erosion signature (delta Ro vs no-erosion run)", "expected": 0.05665081052235643}]'::jsonb then 'old'
              when md5(prompt) = 'c26faeed02700a10fd5c4a6f89c5a865' and fields = '[{"key": "final_ro", "tol": 0.002, "unit": "%Ro", "label": "Source rock final Ro", "expected": 1.6718288798752388}, {"key": "final_temp", "tol": 0.1, "unit": "degC", "label": "Source rock final temperature", "expected": 149.76037539670858}, {"key": "final_tr", "tol": 0.002, "unit": "frac", "label": "Final transformation ratio", "expected": 0.7423743797385286}, {"key": "generated", "tol": 5, "unit": "kg/m2", "label": "Generated mass at present day", "expected": 13946.54641524398}, {"key": "expelled", "tol": 5, "unit": "kg/m2", "label": "Expelled mass at present day", "expected": 10048.985378825158}, {"key": "ro_delta", "tol": 0.001, "unit": "%Ro", "label": "Erosion signature (delta Ro vs no-erosion run)", "expected": 0.05665081052235643}]'::jsonb then 'new'
              else 'other' end
    into v_s2 from public.academy_capstones where app_slug = 'basin' and tier = 'advanced' and active;
  if v_s2 = 'other' then
    raise exception 'w1 open-book basin refused: basin/advanced matches neither its published form (prompt md5 47145f31ec835cc158251fb51e5679c6) nor its W1 form (prompt md5 c26faeed02700a10fd5c4a6f89c5a865), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W1 form
  if v_s0 = 'new' and v_s1 = 'new' and v_s2 = 'new' then
    raise notice 'w1 open-book basin: 0 of 3 row(s) written, all already applied';
    return;
  end if;

  -- the round-off batch (20261023*) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active and md5(prompt) <> '7e7412057740dcb01936e298c2026745')
     or exists (select 1 from public.academy_capstones where app_slug = 'casingtubing' and tier = 'advanced' and active and md5(prompt) <> 'f7e6749b9be66d4dbc7e692745d656d7')
     or exists (select 1 from public.academy_capstones where app_slug = 'gaswell' and tier = 'advanced' and active and md5(prompt) <> '07f6076362de4a93714236cc10af4012')
     or exists (select 1 from public.academy_capstones where app_slug = 'wellcontrol' and tier = 'beginner' and active and md5(dataset) <> '228b1d1a73f0474291f6142741bab7b2')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'fiscal' and c.tier = 'intermediate' and c.active and f->>'key' = 'psc_npv_musd'
                   and (f->>'tol')::float8 <> 0.05) then
    raise exception 'w1 open-book basin refused: the round-off batch (20261023*) is not applied on this database; apply it first (/root/roundoff-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. Work the compaction and heat fundamentals: the solid (grain) thickness inside 100 m of freshly deposited shale; that same 100 m of shale buried to 1000 m and restored to the surface; shale porosity at 2000 m on the Sclater-Christie curve (0.63, 0.00051/m); and the golden two-layer steady heat column (10 C surface, 60 mW/m2 basal, k 1.8 over k 3.5, ten 100 m cells per layer) read at the first cell, the base of the low-conductivity layer, and the deepest cell.',
           fields = '[{"key": "solid_100", "tol": 0.05, "unit": "m", "label": "Solid thickness in 100 m of surface shale", "expected": 38.57953418711555}, {"key": "restored", "tol": 0.05, "unit": "m", "label": "100 m shale from 1000 m, restored to surface", "expected": 159.79553483785466}, {"key": "phi_2000", "tol": 0.001, "unit": "v/v", "label": "Shale porosity at 2000 m", "expected": 0.22717481230903933}, {"key": "t_first", "tol": 0.05, "unit": "degC", "label": "Temperature at the first cell (50 m)", "expected": 11.666666666666671}, {"key": "t_lowk_base", "tol": 0.05, "unit": "degC", "label": "Temperature at the low-k base (950 m)", "expected": 41.66666666666673}, {"key": "t_deepest", "tol": 0.05, "unit": "degC", "label": "Temperature at the deepest cell (1950 m)", "expected": 59.619047619047684}]'::jsonb
     where app_slug = 'basin' and tier = 'beginner' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book basin refused: basin/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '844a4224438738a8982ca478e1264f63' and fields = '[{"key": "solid_100", "tol": 0.05, "unit": "m", "label": "Solid thickness in 100 m of surface shale", "expected": 38.57953418711555}, {"key": "restored", "tol": 0.05, "unit": "m", "label": "100 m shale from 1000 m, restored to surface", "expected": 159.79553483785466}, {"key": "phi_2000", "tol": 0.001, "unit": "v/v", "label": "Shale porosity at 2000 m", "expected": 0.22717481230903933}, {"key": "t_first", "tol": 0.05, "unit": "degC", "label": "Temperature at the first cell (50 m)", "expected": 11.666666666666671}, {"key": "t_lowk_base", "tol": 0.05, "unit": "degC", "label": "Temperature at the low-k base (950 m)", "expected": 41.66666666666673}, {"key": "t_deepest", "tol": 0.05, "unit": "degC", "label": "Temperature at the deepest cell (1950 m)", "expected": 59.619047619047684}]'::jsonb) from public.academy_capstones where app_slug = 'basin' and tier = 'beginner' and active) is not true then
    raise exception 'w1 open-book basin refused: basin/beginner does not read back as its W1 form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. Run the Sweeney-Burnham Easy%Ro integrator and the Type II kerogen clock: vitrinite reflectance at zero and at full reaction; Ro at 150 C on the 3 C/Ma heating ramp and on the slower 1 C/Ma ramp (the same temperature, more time, more maturity); and the isothermal Type II transformation ratio at 100 C after 10 and after 50 Ma.',
           fields = '[{"key": "ro_f0", "tol": 0.001, "unit": "%Ro", "label": "Ro at zero reaction", "expected": 0.20189651799465538}, {"key": "ro_full", "tol": 0.005, "unit": "%Ro", "label": "Ro at full reaction", "expected": 4.687971627022019}, {"key": "ro_150_r3", "tol": 0.002, "unit": "%Ro", "label": "Ro at 150 C on the 3 C/Ma ramp", "expected": 0.9871413464062039}, {"key": "ro_150_r1", "tol": 0.002, "unit": "%Ro", "label": "Ro at 150 C on the 1 C/Ma ramp", "expected": 1.1129254516555198}, {"key": "tr_10", "tol": 0.0005, "unit": "frac", "label": "Type II TR after 10 Ma at 100 C", "expected": 0.022481215976523083}, {"key": "tr_50", "tol": 0.0005, "unit": "frac", "label": "Type II TR after 50 Ma at 100 C", "expected": 0.05477927380797565}]'::jsonb
     where app_slug = 'basin' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book basin refused: basin/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '070f9311e9275c498804b1ec915a5433' and fields = '[{"key": "ro_f0", "tol": 0.001, "unit": "%Ro", "label": "Ro at zero reaction", "expected": 0.20189651799465538}, {"key": "ro_full", "tol": 0.005, "unit": "%Ro", "label": "Ro at full reaction", "expected": 4.687971627022019}, {"key": "ro_150_r3", "tol": 0.002, "unit": "%Ro", "label": "Ro at 150 C on the 3 C/Ma ramp", "expected": 0.9871413464062039}, {"key": "ro_150_r1", "tol": 0.002, "unit": "%Ro", "label": "Ro at 150 C on the 1 C/Ma ramp", "expected": 1.1129254516555198}, {"key": "tr_10", "tol": 0.0005, "unit": "frac", "label": "Type II TR after 10 Ma at 100 C", "expected": 0.022481215976523083}, {"key": "tr_50", "tol": 0.0005, "unit": "frac", "label": "Type II TR after 50 Ma at 100 C", "expected": 0.05477927380797565}]'::jsonb) from public.academy_capstones where app_slug = 'basin' and tier = 'intermediate' and active) is not true then
    raise exception 'w1 open-book basin refused: basin/intermediate does not read back as its W1 form';
  end if;

  if v_s2 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. Run the full forward model on the golden reference basin (four layers over 150 Ma, cooling 80 to 60 mW/m2 heat flow, 600 m of erosion at 10 Ma) and read the source shale at present day: reflectance, temperature, transformation ratio, generated and expelled mass. Then rerun WITHOUT the erosion event and report the erosion signature, the difference in final Ro between the two runs.',
           fields = '[{"key": "final_ro", "tol": 0.002, "unit": "%Ro", "label": "Source rock final Ro", "expected": 1.6718288798752388}, {"key": "final_temp", "tol": 0.1, "unit": "degC", "label": "Source rock final temperature", "expected": 149.76037539670858}, {"key": "final_tr", "tol": 0.002, "unit": "frac", "label": "Final transformation ratio", "expected": 0.7423743797385286}, {"key": "generated", "tol": 5, "unit": "kg/m2", "label": "Generated mass at present day", "expected": 13946.54641524398}, {"key": "expelled", "tol": 5, "unit": "kg/m2", "label": "Expelled mass at present day", "expected": 10048.985378825158}, {"key": "ro_delta", "tol": 0.001, "unit": "%Ro", "label": "Erosion signature (delta Ro vs no-erosion run)", "expected": 0.05665081052235643}]'::jsonb
     where app_slug = 'basin' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book basin refused: basin/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'c26faeed02700a10fd5c4a6f89c5a865' and fields = '[{"key": "final_ro", "tol": 0.002, "unit": "%Ro", "label": "Source rock final Ro", "expected": 1.6718288798752388}, {"key": "final_temp", "tol": 0.1, "unit": "degC", "label": "Source rock final temperature", "expected": 149.76037539670858}, {"key": "final_tr", "tol": 0.002, "unit": "frac", "label": "Final transformation ratio", "expected": 0.7423743797385286}, {"key": "generated", "tol": 5, "unit": "kg/m2", "label": "Generated mass at present day", "expected": 13946.54641524398}, {"key": "expelled", "tol": 5, "unit": "kg/m2", "label": "Expelled mass at present day", "expected": 10048.985378825158}, {"key": "ro_delta", "tol": 0.001, "unit": "%Ro", "label": "Erosion signature (delta Ro vs no-erosion run)", "expected": 0.05665081052235643}]'::jsonb) from public.academy_capstones where app_slug = 'basin' and tier = 'advanced' and active) is not true then
    raise exception 'w1 open-book basin refused: basin/advanced does not read back as its W1 form';
  end if;

  raise notice 'w1 open-book basin: % of 3 row(s) written, % already applied', v_written, 3 - v_written;
end $$;
